package com.bank.workloads;

import java.util.*;
import java.util.logging.Logger;

// Keeps a desired number of identical replicas; self-heals.
public class ReplicaSet {
    private static final Logger log = Logger.getLogger(ReplicaSet.class.getName());
    private final String image;
    private final int desired;
    private final List<Pod> pods = new ArrayList<>();

    public ReplicaSet(String name, String image, int desired) {
        this.image = image;
        this.desired = desired;
        for (int i = 0; i < desired; i++) pods.add(new Pod(name + "-" + i, image, null));
    }

    public void reconcile() {
        while (pods.size() < desired) {
            Pod p = new Pod("replacement-" + pods.size(), image, null);
            pods.add(p);
            log.info(() -> "ReplicaSet self-healed: created " + p.getName());
        }
    }
    public void killOne() { if (!pods.isEmpty()) pods.remove(0); }
    public int running()  { return pods.size(); }
    public List<Pod> pods(){ return pods; }
}
