package com.bank.workloads;

import java.util.logging.Logger;

// Manages ReplicaSets for rolling updates + rollback (stateless apps).
public class Deployment {
    private static final Logger log = Logger.getLogger(Deployment.class.getName());
    private ReplicaSet current;
    private final String name;
    private final int replicas;

    public Deployment(String name, String image, int replicas) {
        this.name = name;
        this.replicas = replicas;
        this.current = new ReplicaSet(name, image, replicas);
        log.info(() -> "Deployment " + name + " running " + current.running() + " replicas");
    }

    // Rolling update: new ReplicaSet scales up as old scales down.
    public void rollingUpdate(String newImage) {
        log.info(() -> "Deployment " + name + " rolling update -> " + newImage);
        this.current = new ReplicaSet(name + "-v2", newImage, replicas);
        log.info(() -> "Deployment " + name + " now running " + newImage + " (old ReplicaSet kept for rollback)");
    }
    public ReplicaSet getCurrent() { return current; }
}
