package com.bank.workloads;

import java.util.*;
import java.util.logging.Logger;

// Stable ordinal identity + a persistent volume bound to each pod.
public class StatefulSet {
    private static final Logger log = Logger.getLogger(StatefulSet.class.getName());
    private final List<Pod> pods = new ArrayList<>();

    public StatefulSet(String name, String image, int replicas) {
        for (int i = 0; i < replicas; i++) {
            // Each pod: stable name db-0, db-1 ... and its OWN volume pvc-db-i.
            pods.add(new Pod(name + "-" + i, image, "pvc-" + name + "-" + i));
        }
    }

    // Rescheduling keeps the SAME name and volume (identity is stable).
    public void reschedule(int ordinal) {
        Pod p = pods.get(ordinal);
        log.info(() -> "StatefulSet rescheduled " + p.getName()
                + " -> SAME volume " + p.getBoundVolume() + " (identity preserved)");
    }
    public List<Pod> pods() { return pods; }
}
