package com.bank.workloads;

import java.util.*;
import java.util.logging.Logger;

// Exactly one pod per node; adds a pod when a node joins.
public class DaemonSet {
    private static final Logger log = Logger.getLogger(DaemonSet.class.getName());
    private final String image;
    private final Map<String, Pod> perNode = new LinkedHashMap<>();

    public DaemonSet(String image, List<String> nodes) {
        this.image = image;
        nodes.forEach(this::ensureOnNode);
    }
    public void ensureOnNode(String node) {
        perNode.put(node, new Pod("agent-" + node, image, null));
        log.info(() -> "DaemonSet placed one agent on " + node);
    }
    public int podCount() { return perNode.size(); }
}
