package com.bank.workloads;

import java.util.logging.Logger;

// Runs a finite task to successful completion, retrying on failure.
public class Job {
    private static final Logger log = Logger.getLogger(Job.class.getName());
    private final String name;
    private final int backoffLimit;

    public Job(String name, int backoffLimit) {
        this.name = name;
        this.backoffLimit = backoffLimit;
    }

    // failuresBeforeSuccess simulates transient failures then success.
    public boolean run(int failuresBeforeSuccess) {
        for (int attempt = 1; attempt <= backoffLimit + 1; attempt++) {
            if (attempt <= failuresBeforeSuccess) {
                final int a = attempt;
                log.warning(() -> "Job " + name + " attempt " + a + " FAILED, retrying");
            } else {
                final int a = attempt;
                log.info(() -> "Job " + name + " attempt " + a + " COMPLETED successfully");
                return true;
            }
        }
        log.severe("Job " + name + " exhausted backoffLimit -> marked failed");
        return false;
    }
}
