package com.bank.workloads;

import java.util.List;
import java.util.logging.*;

public class WorkloadsDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new WorkloadsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(WorkloadsDemo.class.getName());

        log.info("=== Deployment (stateless transfer-service): self-heal + rolling update ===");
        Deployment deploy = new Deployment("transfer-service", "transfer:1.0.0", 3);
        deploy.getCurrent().killOne();          // a pod dies
        deploy.getCurrent().reconcile();        // ReplicaSet self-heals
        deploy.rollingUpdate("transfer:1.1.0"); // rolling update

        log.info("=== StatefulSet (ledger-db): stable identity + volume ===");
        StatefulSet db = new StatefulSet("ledger-db", "postgres:16", 3);
        db.pods().forEach(p -> log.info("  " + p.getName() + " -> volume " + p.getBoundVolume()));
        db.reschedule(1);                       // db-1 keeps its volume

        log.info("=== DaemonSet (log-agent): one per node ===");
        DaemonSet agents = new DaemonSet("log-agent:2.3", List.of("node-a", "node-b"));
        agents.ensureOnNode("node-c");          // new node joins
        log.info("  total agents = " + agents.podCount());

        log.info("=== Job (end-of-day reconciliation): run to completion ===");
        new Job("eod-reconciliation", 3).run(2); // fails twice then succeeds
    }
}

